import fs from 'fs'
const p = 'dist/assets'
let hits = 0
let stale = 0
for (const f of fs.readdirSync(p).filter((x) => x.endsWith('.js'))) {
  const s = fs.readFileSync(p + '/' + f, 'utf8')
  if (s.includes('项目所在地')) {
    if (s.includes('formatter:' + JSON.stringify('fullRegionFormatter'))) hits++
    else if (s.includes('prop:' + JSON.stringify('regionName'))) stale++
  }
}
console.log('fixed_chunks=' + hits, 'stale_regionName_chunks=' + stale)
